823      private SingleFcn bestMatchWithCoercion(List<FValue> args, List<Overload> someOverloads) {
824          Coercions.CoercedCall best = null;
825          SingleFcn bestUnconverted = null;
826          List<Coercions.CoercedCall> applicable = new ArrayList<Coercions.CoercedCall>();
827          for (Overload o : someOverloads) {
828              SingleFcn sfn = o.getFn();
829              if (sfn instanceof GenericFunctionOrMethod) {
830                  GenericFunctionOrMethod gsfn = (GenericFunctionOrMethod) sfn;
831                  try {
832                      sfn = EvaluatorBase.inferAndInstantiateGenericFunction(args, gsfn, gsfn.getWithin());
833                  }
834                  catch (FortressException pe) {
835                      continue;
836                  }
837              }
838              List<FValue> oargs = sfn.fixupArgCount(args);
839              if (oargs == null) continue;
840              List<FType> domain = sfn.getDomain();
841              SingleFcn[] coercions = new SingleFcn[oargs.size()];
842              boolean applies = true;
843              boolean converts = false;
844              for (int j = 0; applies && j < oargs.size(); j++) {
845                  FType t = Useful.clampedGet(domain, j).deRest();
846                  FValue a = oargs.get(j);
847                  if (!argsMatchTypes(Collections.singletonList(a), Collections.singletonList(t))) {
848                      coercions[j] = Coercions.coercionFor(t, a);
849                      applies = coercions[j] != null;
850                      converts = true;
851                  }
852              }
853              if (!applies) continue;
854              Coercions.CoercedCall c = new Coercions.CoercedCall(sfn, coercions, this);
855              applicable.add(c);
856              if (best == null || Coercions.moreSpecific(domain, best.getDomain(), oargs.size())) {
857                  best = c;
858                  bestUnconverted = converts ? null : sfn;
859              }
860          }
861          for (Coercions.CoercedCall c : applicable) {
862              if (c != best && !Coercions.moreSpecific(best.getDomain(), c.getDomain(), best.arity())) {
863                  return error(errorMsg("Ambiguous coercion, args = ",
864                                        Useful.listInParens(args),
865                                        ", applicable with coercion = ",
866                                        Useful.listInDelimiters("{", applicable, "}")));
867              }
868          }
869          return bestUnconverted != null ? bestUnconverted : best;
870      }

